var outfits=[{"id": "rl-chilly-m35-night-street-20261026-01", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "street", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/street/01/editorial.jpg", "deck": {"ko": "젖은 연석도 가볍게 건너는, 차콜 톤의 묵직한 밤 스트리트 룩.", "en": "A heavy charcoal night look that still hops a wet kerb lightly.", "de": "Ein schwerer anthrazitfarbener Abendlook, der trotzdem leichtfüßig über die nasse Bordsteinkante springt."}, "items": ["rl-chilly-m35-night-street-20261026-01.01-outer", "rl-chilly-m35-night-street-20261026-01.02-top", "rl-chilly-m35-night-street-20261026-01.03-bottom", "rl-chilly-m35-night-street-20261026-01.04-shoes", "rl-chilly-m35-night-street-20261026-01.05-bag"], "article": {"title": "THE CHARCOAL PARKA TAKES THE KERB", "intro": {"ko": "긴 차콜 파카 안에 도톰한 오트밀 니트를 겹치고, 넉넉한 인디고 데님과 러그 부츠로 무게를 맞췄습니다. 크로스보디 백은 몸 가까이 짧게 메어 움직임을 편하게 정리하세요.", "en": "A thick oatmeal knit goes inside the long charcoal parka, with roomy indigo denim and lug-sole boots to balance the weight. Wear the crossbody bag short and close to the body so you can move freely.", "de": "Unter dem langen anthrazitfarbenen Parka liegt ein dicker haferbeiger Strick; weite Indigo-Jeans und Boots mit Profilsohle gleichen das Gewicht aus. Die Crossbodytasche kurz und nah am Körper tragen, damit die Bewegung frei bleibt."}, "pull": "ONE STEP OVER THE PUDDLE, STILL SMILING.", "tip": {"ko": "긴 파카 밑단이 물웅덩이에 닿지 않도록 걸음을 조금 크게 내딛으세요.", "en": "Take a slightly longer step so the long parka hem stays clear of the puddles.", "de": "Etwas größere Schritte machen, damit der lange Parkasaum nicht in die Pfützen hängt."}}, "hero": "rl-chilly-m35-night-street-20261026-01.01-outer"}, {"id": "rl-chilly-m35-night-street-20261026-02", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "street", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/street/02/editorial.jpg", "deck": {"ko": "문 앞에서 비니의 빗물을 털어내는, 스톤과 브라운의 차분한 밤.", "en": "Shaking the rain off a beanie at the door, in calm shades of stone and brown.", "de": "An der Tür das Regenwasser aus der Mütze schütteln – in ruhigen Stein- und Brauntönen."}, "items": ["rl-chilly-m35-night-street-20261026-02.01-outer", "rl-chilly-m35-night-street-20261026-02.02-top", "rl-chilly-m35-night-street-20261026-02.03-bottom", "rl-chilly-m35-night-street-20261026-02.04-shoes", "rl-chilly-m35-night-street-20261026-02.05-head"], "article": {"title": "STONE JACKET, BEANIE SHAKEN DRY", "intro": {"ko": "스톤 재킷 아래 초콜릿 후디를 겹쳐 후드와 목선에 깊이를 줍니다. 넓은 차콜 팬츠의 밑단을 가볍게 정리하고, 어두운 레더 슈즈와 블랙 비니로 마무리하세요.", "en": "A chocolate hoodie under the stone jacket gives the hood and neckline depth. Keep the hems of the wide charcoal trousers tidy and finish with dark leather shoes and a black beanie.", "de": "Ein schokoladenbrauner Hoodie unter der steinfarbenen Jacke gibt Kapuze und Ausschnitt Tiefe. Die Säume der weiten anthrazitfarbenen Hose ordentlich halten und mit dunklen Lederschuhen und schwarzer Mütze abschließen."}, "pull": "A SHAKE AT THE DOOR, AND THE NIGHT STAYS OUTSIDE.", "tip": {"ko": "젖은 비니는 문 밖에서 가볍게 털고, 실내에서는 펴서 말리세요.", "en": "Shake a wet beanie out before you go in, then lay it flat to dry indoors.", "de": "Eine nasse Mütze vor der Tür ausschütteln und drinnen flach zum Trocknen hinlegen."}}, "hero": "rl-chilly-m35-night-street-20261026-02.01-outer"}, {"id": "rl-chilly-m35-night-street-20261026-03", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "street", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/street/03/editorial.jpg", "deck": {"ko": "자전거 자물쇠 앞에 쪼그려 앉아도 선명하게 남는 코발트 한 점.", "en": "One clear note of cobalt, even crouched at the bike lock.", "de": "Ein klarer Kobaltton, selbst in der Hocke am Fahrradschloss."}, "items": ["rl-chilly-m35-night-street-20261026-03.01-outer", "rl-chilly-m35-night-street-20261026-03.02-top", "rl-chilly-m35-night-street-20261026-03.03-bottom", "rl-chilly-m35-night-street-20261026-03.04-shoes", "rl-chilly-m35-night-street-20261026-03.05-bag"], "article": {"title": "COBALT JACKET AT THE BIKE LOCK", "intro": {"ko": "코발트 재킷을 중심으로 플리스와 카고 팬츠, 부츠를 차콜과 블랙으로 연결했습니다. 작은 숄더백을 몸 가까이 메고, 목까지 올라오는 이너로 쌀쌀한 밤의 레이어를 완성하세요.", "en": "The cobalt jacket sits at the centre, with fleece, cargo trousers and boots linked in charcoal and black. Wear the small shoulder bag close, and let a layer that comes up to the neck finish the layering for a chilly night.", "de": "Die Kobaltjacke steht im Mittelpunkt, Fleece, Cargohose und Boots verbinden sich in Anthrazit und Schwarz. Die kleine Umhängetasche nah am Körper tragen; eine bis zum Hals reichende Lage vollendet die Schichten für den kühlen Abend."}, "pull": "KEYS OUT, LOCK OPEN, BACK ON THE ROAD.", "tip": {"ko": "젖은 자전거 안장은 출발 전에 손으로 한 번 닦아 내세요.", "en": "Wipe the wet saddle with your hand before you ride off.", "de": "Den nassen Sattel vor dem Losfahren kurz mit der Hand abwischen."}}, "hero": "rl-chilly-m35-night-street-20261026-03.01-outer"}, {"id": "rl-chilly-m35-night-street-20261026-04", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "street", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/street/04/editorial.jpg", "deck": {"ko": "와인 가게 앞에서 머플러를 고쳐 매는, 올리브와 그레이의 따뜻한 밤.", "en": "Settling a scarf outside the wine shop, in warm olive and grey.", "de": "Vor dem Weinladen den Schal zurechtrücken – in warmem Oliv und Grau."}, "items": ["rl-chilly-m35-night-street-20261026-04.01-outer", "rl-chilly-m35-night-street-20261026-04.02-top", "rl-chilly-m35-night-street-20261026-04.03-bottom", "rl-chilly-m35-night-street-20261026-04.04-shoes", "rl-chilly-m35-night-street-20261026-04.05-neck"], "article": {"title": "OLIVE PARKA OUTSIDE THE WINE SHOP", "intro": {"ko": "올리브 파카와 크림 스웨트셔츠 사이에 그레이 머플러를 자연스럽게 늘어뜨립니다. 브라운 코듀로이 팬츠와 어두운 부츠로 색의 온도를 이어가되 머플러 끝은 몸 가까이 정리하세요.", "en": "A grey scarf hangs loosely between the olive parka and the cream sweatshirt. Brown corduroy and dark boots carry the warmth of the colours down, while the scarf ends stay close to the body.", "de": "Zwischen olivgrünem Parka und cremefarbenem Sweatshirt hängt locker ein grauer Schal. Braune Cordhose und dunkle Boots tragen die Wärme der Farben nach unten, die Schalenden bleiben nah am Körper."}, "pull": "A HAND AT THE SCARF, A GLANCE BACK AT THE DOOR.", "tip": {"ko": "비에 젖은 머플러 끝은 파카 안쪽으로 넣어 두면 덜 무거워져요.", "en": "Tuck damp scarf ends inside the parka so they don't grow heavy in the rain.", "de": "Feuchte Schalenden in den Parka stecken, damit sie im Regen nicht schwer werden."}}, "hero": "rl-chilly-m35-night-street-20261026-04.01-outer"}, {"id": "rl-chilly-m35-night-street-20261026-05", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "street", "gender": "m", "age": "35", "time": "evening", "image": "look/berlin-complete/Rain/Light/Chilly/Male/35+/night/street/05/editorial.jpg", "deck": {"ko": "현관 계단에 한 발 올리며 돌아보는, 번트 오렌지 하나로 밝힌 밤.", "en": "One foot on the doorstep and a look back, the night lit by a single burnt orange.", "de": "Ein Fuß auf der Stufe, ein Blick zurück – der Abend leuchtet in einem einzigen Rostorange."}, "items": ["rl-chilly-m35-night-street-20261026-05.01-outer", "rl-chilly-m35-night-street-20261026-05.02-top", "rl-chilly-m35-night-street-20261026-05.03-bottom", "rl-chilly-m35-night-street-20261026-05.04-shoes", "rl-chilly-m35-night-street-20261026-05.05-bag"], "article": {"title": "BURNT ORANGE JACKET, ONE STEP UP", "intro": {"ko": "번트 오렌지 재킷에 딥 네이비 니트와 그래파이트 팬츠를 겹쳐 색을 절제했습니다. 블랙 크로스보디 백과 브라운 부츠로 연결하고, 가방 끈은 재킷의 어깨선에 맞춰 정리하세요.", "en": "A deep navy knit and graphite trousers under the burnt orange jacket keep the colour restrained. A black crossbody bag and brown boots tie it together; set the bag strap along the jacket's shoulder line.", "de": "Dunkelblauer Strick und graphitgraue Hose unter der rostorangen Jacke halten die Farbe zurück. Schwarze Crossbodytasche und braune Boots verbinden alles; den Taschengurt entlang der Schulterlinie der Jacke legen."}, "pull": "ONE STEP UP, ONE LOOK BACK.", "tip": {"ko": "젖은 돌계단에서는 굽 전체가 닿게 디디고 한 계단씩 오르세요.", "en": "On wet stone steps, set your whole heel down and climb one step at a time.", "de": "Auf nassen Steinstufen den ganzen Absatz aufsetzen und Stufe für Stufe hinaufgehen."}}, "hero": "rl-chilly-m35-night-street-20261026-05.01-outer"}];
